                          <div className="section-list">
                            {(cls.sections || []).map((s, si) => (
                              <div key={si} className="section-row-item">
                                <span className="sec-name"><i className="fas fa-circle" style={{ fontSize: 7, color: 'var(--brand-primary)' }}></i>{s}</span>
